import{_ as c,o,c as t,a5 as n}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Plan — G3 Agency / Workspace (Mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g3-agency-workspace/plan.md","filePath":"mobile/features/g3-agency-workspace/plan.md"}'),r={name:"mobile/features/g3-agency-workspace/plan.md"};function a(i,e,l,h,s,d){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="plan-—-g3-agency-workspace-mobile" tabindex="-1">Plan — G3 Agency / Workspace (Mobile) <a class="header-anchor" href="#plan-—-g3-agency-workspace-mobile" aria-label="Permalink to &quot;Plan — G3 Agency / Workspace (Mobile)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — chi tiết API/flows/business rules đầy đủ. File này là bản tóm tắt thứ tự implement + quyết định kỹ thuật chốt.</p><h2 id="thu-tu-implement-theo-dependency" tabindex="-1">Thứ tự implement (theo dependency) <a class="header-anchor" href="#thu-tu-implement-theo-dependency" aria-label="Permalink to &quot;Thứ tự implement (theo dependency)&quot;">​</a></h2><ol><li><strong>Infra trước — G4-G7 phụ thuộc trực tiếp vào store này:</strong><ul><li><code>useCurrentWorkspaceStore</code> (Zustand): <code>currentWorkspace</code>, <code>currentMemberRole</code> (derive từ <code>myRole</code>, KHÔNG set tay riêng), <code>currentAgencyId</code> (derive từ <code>agencyId</code>).</li><li>Persist chỉ <code>currentWorkspace.id</code> vào AsyncStorage/SecureStore (không persist cả object) — fetch lại <code>GET /workspaces/{id}</code> khi app mở lại để tránh stale data.</li><li>Clear store khi logout, đồng bộ với <code>clearAuth()</code> (G1) — tránh lẫn session user khác.</li></ul></li><li><strong>Agency screens:</strong> List → Dashboard/Profile → Member List + drawer → Invite modal → Pending Invitations.</li><li><strong>Workspace screens:</strong> List theo Agency đã chọn → Detail (tab Profile <strong>chặn bởi <code>timezoneConfig</code> thiếu field</strong>, tab Members) → Invite/Assign/Update-Role/Remove Member → Leave Workspace → Workspace Switcher.</li></ol><h2 id="quyet-đinh-ky-thuat-đa-chot" tabindex="-1">Quyết định kỹ thuật đã chốt <a class="header-anchor" href="#quyet-đinh-ky-thuat-đa-chot" aria-label="Permalink to &quot;Quyết định kỹ thuật đã chốt&quot;">​</a></h2><ul><li><strong>Role luôn đọc theo <code>currentWorkspace.myRole</code>, không cache 1 role duy nhất per-user toàn app</strong> — 1 user có thể là MANAGER ở Workspace X nhưng chỉ CREATOR ở Workspace Y cùng 1 Agency (CONFIRMED trong BA doc).</li><li><strong>Workspace Switcher = &quot;role switcher&quot; duy nhất</strong> — không có màn role switcher riêng, role luôn gắn theo workspace đang chọn.</li><li><strong>2 tầng permission tách biệt</strong>: Agency-level (check <code>ownerId</code>, không dùng <code>MemberRole</code>) và Workspace-level (<code>@RequireRole(MemberRole...)</code>). UI phải phân biệt rõ, không gộp chung logic hiển thị quyền.</li><li><strong>Điều kiện add vào Workspace</strong>: user phải đã là Agency Member trước — nếu chưa, UI chặn/gợi ý &quot;Invite to Agency first&quot; thay vì gọi API rồi nhận lỗi 409 (UX chủ động, không dựa vào lỗi server).</li></ul><h2 id="viec-can-xac-nhan-truoc-khi-code-chua-lam-xem-spec-muc-8" tabindex="-1">Việc cần xác nhận trước khi code (chưa làm, xem spec mục 8) <a class="header-anchor" href="#viec-can-xac-nhan-truoc-khi-code-chua-lam-xem-spec-muc-8" aria-label="Permalink to &quot;Việc cần xác nhận trước khi code (chưa làm, xem spec mục 8)&quot;">​</a></h2><ul><li><code>timezoneConfig</code> thiếu trong <code>WorkspaceResponse</code> dù model <code>Workspace.java</code> có field này — <strong>chặn thiết kế UI Workspace Profile</strong>, cần hỏi BE bổ sung field hay dùng API khác.</li><li><code>AgencyMemberProfileResponse</code>/<code>AuditLogResponse</code> chưa đọc chi tiết field — đọc trước khi code Member Profile drawer; có thể cắt Activity Feed ở bản đầu để giảm scope.</li><li><code>ManagedWorkspaceResponse</code> (<code>/workspaces/my-managed</code>) chưa đọc field — đọc trước khi code shortcut &quot;My Managed Workspaces&quot;.</li><li>Deep-link accept invitation qua token — xác nhận Expo app đã config scheme <code>brandhub</code> (đã chốt ở G1) có dùng lại được cho flow này không.</li><li>Agency Owner xem Workspace không phải Manager/Member — hành vi thật của <code>@RequireRole</code> + service layer override cần test API thật trước khi dựa vào.</li></ul><h2 id="rui-ro-con-mo" tabindex="-1">Rủi ro còn mở <a class="header-anchor" href="#rui-ro-con-mo" aria-label="Permalink to &quot;Rủi ro còn mở&quot;">​</a></h2><ul><li>Nếu backend chưa bổ sung <code>timezoneConfig</code>, mobile tạm thời ẩn field Timezone ở Workspace Profile thay vì hiển thị sai/trống — cần quyết định UI fallback trước khi code màn này.</li></ul>',10)])])}const g=c(r,[["render",a]]);export{p as __pageData,g as default};
